window.kbPageData["views/entry/k-47ca586a22f86a78"] = {"key":"entry/k-47ca586a22f86a78","state":{"route":"entry/k-47ca586a22f86a78"},"node":{"id":"k-47ca586a22f86a78","mode":"k","title":"排列与组合","type":"概念与词义","domain":"数学","reading":"","intro":"","priority":100,"aliases":["排列与组合的区别"],"qs":["江苏 2024 A类 行测#62"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"从不同元素中选取若干个元素，只区分选中的元素时用组合，还要区分这些元素的顺序时用排列。分配到不同位置时，交换去向也会产生不同结果。","review":{"definition":"从不同元素中选取若干个元素，只区分选中的元素时用组合，还要区分这些元素的顺序时用排列。分配到不同位置时，交换去向也会产生不同结果。","explanation":"两个二线城市各占1人，两个一线城市因此分别派2人和1人。先从5人中选2人组成一组，有10种，同一组内交换两人的顺序仍是同一组。再从剩余3人中选1人，有3种。将这两组派往两个不同的一线城市有2种，剩下两人分派到两个不同的二线城市也有2种，共10×3×2×2＝120种，选C。","references":[],"evidence":"这两组人分配到2个一线城市","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#62":{"paper":"江苏 2024 A类 行测","n":62,"mod":"数量关系","src":["f8fec75f67d6d1ba5759.pdf",11],"asrc":["0126a1c8aceee632ea2b.pdf",18],"card":"3125fb2194e994fd1c46cff3","links":[{"id":"k-47ca586a22f86a78","role":"解题依据","why":"组内选人无需区分顺序，派往不同城市则需要区分去向。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-47ca586a22f86a78":[["江苏 2024 A类 行测#62"]]}};
